package org.sleepwell.app;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.os.*;import android.view.*;import android.widget.*;
import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.UiDevice;
import org.junit.Test;import java.io.File;import java.util.*;import static org.junit.Assert.*;
/** The real output-free preview; never opens an alarm or starts its service. */
public final class MoonSearchFlowTest {
    final Instrumentation i=InstrumentationRegistry.getInstrumentation();final Context c=i.getTargetContext();final UiDevice d=UiDevice.getInstance(i);MoonSearchPreviewActivity activity;
    void await(java.util.function.BooleanSupplier yes)throws Exception{long until=SystemClock.elapsedRealtime()+8000;while(!yes.getAsBoolean()&&SystemClock.elapsedRealtime()<until)Thread.sleep(20);assertTrue("Search preview ready",yes.getAsBoolean());}
    View find(View v,String match){String desc=v.getContentDescription()==null?"":v.getContentDescription().toString();if(desc.startsWith(match)||v instanceof TextView&&match.contentEquals(((TextView)v).getText()))return v;if(v instanceof ViewGroup g)for(int n=0;n<g.getChildCount();n++){View found=find(g.getChildAt(n),match);if(found!=null)return found;}return null;}
    boolean shown(String label){boolean[] yes={false};i.runOnMainSync(()->yes[0]=activity!=null&&activity.hasWindowFocus()&&find(activity.getWindow().getDecorView(),label)!=null);return yes[0];}
    void click(String label)throws Exception{await(()->shown(label));Rect[] rect={null};i.runOnMainSync(()->{View v=find(activity.getWindow().getDecorView(),label);assertTrue(v.isClickable());assertTrue(v.isEnabled());Rect r=new Rect();assertTrue(v.getGlobalVisibleRect(r));assertEquals(v.getHeight(),r.height());assertTrue(r.width()>=Design.dp(c,48));assertTrue(r.height()>=Design.dp(c,48));int[] screen=new int[2];v.getLocationOnScreen(screen);rect[0]=new Rect(screen[0],screen[1],screen[0]+v.getWidth(),screen[1]+v.getHeight());});assertTrue(d.click(rect[0].centerX(),rect[0].centerY()));}
    void capture(String frame)throws Exception{i.waitForIdleSync();File dir=new File(c.getExternalFilesDir(null),"verification");assertTrue(dir.isDirectory()||dir.mkdirs());assertTrue(d.takeScreenshot(new File(dir,"moon-search-"+frame+".png")));}
    @Test public void wrongCellRecreateCorrectCellAndNewBoardUseRealPreviewControls()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",d.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);Map<String,?> prefs=new HashMap<>(Prefs.of(c).getAll());
        try{Instrumentation.ActivityMonitor monitor=i.addMonitor(MoonSearchPreviewActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,MoonSearchPreviewActivity.class).putExtra("visualReview",true).putExtra("verificationLabel","Private challenge preview · no alarm").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(MoonSearchPreviewActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}await(()->shown("Find the sleeping moon"));String[] target={null};i.runOnMainSync(()->target[0]=find(activity.getWindow().getDecorView(),"Sleeping moon,").getContentDescription().toString());capture("initial");click("Awake moon,");await(()->shown("That moon is awake. Keep looking."));assertFalse(shown("Challenge completed"));capture("wrong");MoonSearchPreviewActivity old=activity;monitor=i.addMonitor(MoonSearchPreviewActivity.class.getName(),null,false);try{i.runOnMainSync(old::recreate);activity=(MoonSearchPreviewActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}await(()->shown(target[0]));capture("recreated");click(target[0]);await(()->shown("Challenge completed"));capture("complete");click("Try another board");await(()->shown("Find the sleeping moon"));capture("new-board");
        }finally{if(activity!=null&&!activity.isDestroyed()){MoonSearchPreviewActivity old=activity;i.runOnMainSync(old::finish);await(old::isDestroyed);}assertEquals(prefs,Prefs.of(c).getAll());assertFalse(AlarmService.active);assertFalse(TrackingService.running);}
    }
}
